import{_ as t,o as e,c as d,ag as s}from"./chunks/framework.C5oN-8Wt.js";const n="/cns_master_docs/teaching-v0.4.0-alpha/03-delay-to-distance.svg",_=JSON.parse('{"title":"03 晚了两毫秒，距离是多少？","description":"","frontmatter":{},"headers":[],"relativePath":"v0.4.0-alpha/learn/03-delay-to-distance/index.md","filePath":"v0.4.0-alpha/learn/03-delay-to-distance/index.md"}'),o={name:"v0.4.0-alpha/learn/03-delay-to-distance/index.md"};function l(r,a,p,c,i,h){return e(),d("div",null,[...a[0]||(a[0]=[s(`<h1 id="_03-晚了两毫秒-距离是多少" tabindex="-1">03 晚了两毫秒，距离是多少？ <a class="header-anchor" href="#_03-晚了两毫秒-距离是多少" aria-label="Permalink to &quot;03 晚了两毫秒，距离是多少？&quot;">​</a></h1><p>适用 CNS Master <strong>v0.4.0-alpha</strong>。先手算预测，再运行工程，对照结果。</p><h2 id="低空观测问题与学习目标" tabindex="-1">低空观测问题与学习目标 <a class="header-anchor" href="#低空观测问题与学习目标" aria-label="Permalink to &quot;低空观测问题与学习目标&quot;">​</a></h2><p>地面观测设备若知道信号传播用了多久，还需要知道什么，才能估计距离？本课沿用<a href="./../02-find-delay/">上一课的短序列和两点延时</a>，把“相关峰在哪”依次换成“延迟多少秒”和“传播距离多少米”。它只演示 PC 上的传播时间模型，不接真实目标、声学传感器或雷达。</p><p>学习目标是说明样本数、秒与米之间的换算条件，解释往返为何除以 2，并知道怎样区分负峰、负延迟和失败后的旧读数。</p><h2 id="先备知识-先得到秒-再乘速度" tabindex="-1">先备知识：先得到秒，再乘速度 <a class="header-anchor" href="#先备知识-先得到秒-再乘速度" aria-label="Permalink to &quot;先备知识：先得到秒，再乘速度&quot;">​</a></h2><p>上一课原始采样率为 Fs=1000 sample/s，每个样本间隔 1 ms。lag=+2 表示晚 2 个样本，所以延迟是 <code>2/1000=0.002 s</code>。不能直接拿“2 个样本”乘 m/s，否则单位不相容。</p><p>速度乘时间得到路程。本课特意选择 <strong>340 m/s 的声传播教学速度</strong>，使纸面数值容易核对；这既不是电磁雷达的传播速度，也不是考虑温度、湿度等因素后的声速精度模型。得到 0.34 m 不代表实际设备具有相应测距精度。</p><h2 id="打开本课工程" tabindex="-1">打开本课工程 <a class="header-anchor" href="#打开本课工程" aria-label="Permalink to &quot;打开本课工程&quot;">​</a></h2><p><a href="../../../downloads/teaching-v0.4.0-alpha/03-delay-to-distance.cnsproj" download>下载 03-delay-to-distance.cnsproj</a></p><p>在程序中用“文件 → 打开工程”（<strong>Ctrl+O</strong>）选择下载文件。工程保留上一课的波形和相关图，并增加按单位分别读取 lag、峰值、秒数和距离的观察器。先核对中间结果，再看最终米值。</p><h2 id="接线与选择理由" tabindex="-1">接线与选择理由 <a class="header-anchor" href="#接线与选择理由" aria-label="Permalink to &quot;接线与选择理由&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>向量点表源（实标量）────────→ 相关器 ref</span></span>
<span class="line"><span>                    └→ 延时器 → 相关器 rx</span></span>
<span class="line"><span>                              │ correlation</span></span>
<span class="line"><span>                              ├→ 观察器：单路 lag 图</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>                         峰值检测器</span></span>
<span class="line"><span>                              │ delay_s</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>                            测距器</span></span>
<span class="line"><span>                              │ distance</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>                       观察器：标量距离</span></span></code></pre></div><p>相关器输出的是一帧所有 lag 的相关值；峰值检测器先找<strong>唯一的最大绝对值</strong>，再用相关器记录的真实原始 Fs 将 lag 换成秒；测距器才用秒和传播速度算米。峰值检测器的 <code>lag_samples</code> 与 <code>peak_value</code> 也可独立捕获，便于核对中间步骤。</p><p>峰值检测器只接受相关器的<strong>直接输出</strong>，两者帧长应一致。不要在两者之间插入增益器、加法器或普通向量来源：这些输出没有所需的 lag 轴信息，单凭分量个数相同不能替代。</p><p>本课沿用八点重复参考表 <code>[1,2,1,0,0,0,0,0]</code>，延时 2 点后的完整 rx 帧为 <code>[0,0,1,2,1,0,0,0]</code>。两路原始 Fs 为 1000 sample/s，相关器与峰值检测器的 <code>frame_length</code> 都取 8，峰阈值 <code>min_abs_peak</code> 取 0；测距器显式设 <code>propagation_speed_m_s=340</code>、<code>round_trip=true</code>。阈值 0 表示最大绝对峰仍须严格大于零，不表示无峰也输出零。</p><h2 id="本课设置与操作" tabindex="-1">本课设置与操作 <a class="header-anchor" href="#本课设置与操作" aria-label="Permalink to &quot;本课设置与操作&quot;">​</a></h2><ol><li>先完成上一课图，核对完整 ref、rx 及 15 项相关输出。点表源与延时器仍使用实数 float32、<code>vlen=1</code>；点表源虚部表填八个 0。</li><li>从相关器直接接入峰值检测器，再把其 <code>delay_s</code> 接入测距器。核对两者 N=8，测距器已显式使用 340 m/s 及往返方式。</li><li>图底部“参考源样本数”填 <strong>64</strong>，使相关器每个输入有 Q=64 个样本，形成 8 个完整相关窗。有限输入须满足 <code>Q&gt;=N</code> 且 <code>Q%N==0</code>，不足一窗或有余数都会在准备时报错。</li><li>准备后运行，分别捕获 <code>lag_samples</code>、<code>peak_value</code>、<code>delay_s</code>、<code>distance</code>，记录它们与任务状态。相关完整父向量单独看“相关值—滞后”图，这四个输出分别按标量读取。</li><li>将本次读数与下列手算值比较。任务失败时先读失败原因和对应位置，不把观察器保留的上一帧数据记作本轮结果。</li></ol><h2 id="预期结果-三个换算步骤" tabindex="-1">预期结果：三个换算步骤 <a class="header-anchor" href="#预期结果-三个换算步骤" aria-label="Permalink to &quot;预期结果：三个换算步骤&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>使用的已知条件</th><th>手算参考</th></tr></thead><tbody><tr><td>相关与找峰</td><td>N=8，完整 ref、rx 帧，原始 full 相关</td><td>唯一绝对峰位于 lag=+2，<code>peak_value=+6</code></td></tr><tr><td>样本数换成秒</td><td>原始 Fs=1000 sample/s</td><td><code>delay_s=2/1000=0.002 s</code></td></tr><tr><td>往返传播时间换成距离</td><td>v=340 m/s，往返</td><td><code>distance=340×0.002/2=0.34 m</code></td></tr></tbody></table><p>往返模型假定信号从观测端到目标，再沿返回路径传播，总路程为目标距离的两倍。式中的 0.002 s 是往返总传播时间，除以 2 才是模型中的单边距离。</p><p>本例的相关帧率为 <code>1000/8=125 item/s</code>，但它不替代原始 Fs。误用 <code>2/125</code> 会把时间放大 8 倍。一个相关向量是同一窗口的多个 lag，不是 15 个独立采样时刻。</p><p>相关图应与上一课一致，峰位于 +2。每个完整窗都含相同输入，因此四个标量结果应分别保持在 +2 sample、+6、0.002 s、0.34 m 附近。图的横轴表示帧时刻，不能把这几条不同单位的数值相互比较大小；精确核对时分别读数。</p><p>本轮应得到 8 个完整帧及对应的标量结果。逐项核对 lag、峰值、秒数和米数；Float32 小数计算可能使读数末位略有差异。</p><p>作一个<strong>纸面对照</strong>：如果同样的 0.002 s 被解释为单程传播时间，路程是 <code>340×0.002=0.68 m</code>。这用于解释公式；本课的软件主对照始终保留往返方式，不同时改传播速度或往返选项。</p><h2 id="单参数对照-延时-2-点改成-3-点" tabindex="-1">单参数对照：延时 2 点改成 3 点 <a class="header-anchor" href="#单参数对照-延时-2-点改成-3-点" aria-label="Permalink to &quot;单参数对照：延时 2 点改成 3 点&quot;">​</a></h2><p>等本轮任务完成，只改延时器的延时样本数，从 2 改成 3，再重新准备并运行。保留同一参考表、Fs=1000、N=8、Q=64、峰阈值、速度和往返方式。rx 帧应为 <code>[0,0,0,1,2,1,0,0]</code>，有效短序列仍完整留在窗口里。</p><table tabindex="0"><thead><tr><th>延时设置</th><th>峰位置参考</th><th>有符号峰值参考</th><th>delay_s 参考</th><th>往返 distance 参考</th></tr></thead><tbody><tr><td>2 个样本</td><td>+2 sample</td><td>+6</td><td>0.002 s</td><td>0.34 m</td></tr><tr><td>3 个样本</td><td>+3 sample</td><td>+6</td><td>0.003 s</td><td>0.51 m</td></tr></tbody></table><p>距离增加 <code>0.51−0.34=0.17 m</code>，正好等于本教学模型中一个采样间隔对应的往返距离 <code>340×0.001/2</code>。它说明离散时间换算，不证明真实传感器的分辨率或精度。</p><p>对照下图，延时从 2 点改为 3 点后，秒数从 0.002 增至 0.003，往返模型中的距离从 0.34 m 增至 0.51 m。</p><p><img src="`+n+'" alt="延时 2 点和 3 点对应的秒数与往返距离"></p><h2 id="常见问题与失败含义" tabindex="-1">常见问题与失败含义 <a class="header-anchor" href="#常见问题与失败含义" aria-label="Permalink to &quot;常见问题与失败含义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象或疑问</th><th>应如何理解或检查</th></tr></thead><tbody><tr><td>峰值是负数，是否距离也必须为负？</td><td>峰值保留原始相关符号，表示当前对齐处的乘加方向。反号 rx 在本例可得到 lag=+2、峰值 −6；距离由 delay_s 决定，不能由峰值符号推断。</td></tr><tr><td>出现唯一负 lag</td><td>峰值检测可保留有符号 lag 和负延迟。将负 delay_s 交给测距器会使任务失败，不能取绝对值或截成零得到伪距离。先查两支路顺序与模型。</td></tr><tr><td>唯一零 lag 是否失败？</td><td>若满足峰值规则，零 lag 是合法结果，可对应 0 s 和 0 m。零值不能被用作失败占位。</td></tr><tr><td>全零、并列绝对峰或峰不高于阈值</td><td>含峰值检测器的任务失败；“不高于”包含等于阈值。相关器仍保留数学上的真实帧，不把任意一个并列点选成有效目标。</td></tr><tr><td>任务失败后还有上一条距离</td><td>失败保留最后有效数据及失败状态，不再产生新的有效距离。不要把旧读数或人为补的零记成新结果。</td></tr><tr><td>换成其他信号为什么不一定得到正确距离？</td><td>周期重复可能存在移位歧义，短序列跨窗会被截断，静默窗也可能无峰。唯一原始相关峰只说明本窗口的算术结果，不证明目标存在或抗干扰能力。</td></tr></tbody></table><p>相关器的 N 为整数 8—512。有限运行必须完整分帧，不能补尾；连续运行虽消费完整窗，也不使这套帧模型变成通用连续目标探测。实际雷达和 GNSS 还需要各自的物理模型、时钟、硬件与验证，本课不展开相关课程。</p><p><a href="./../02-find-delay/">← 上一课：相关找延迟</a> · <a href="./../../modules/peak_detector/">峰值检测器参考</a> · <a href="./../../modules/range_estimator/">测距器参考</a> · <a href="./../">返回学习路径</a></p>',35)])])}const g=t(o,[["render",l]]);export{_ as __pageData,g as default};
